action_def.step:
const tickets = $data.tickets || [];
const target = tickets.find(t => String(t.id) === String('{args.id}'));
if (target) {
    target.completed = !target.completed;
    $engine.setState('tickets', [...tickets]);
    $data.simulation_log = `Toggled ticket '${target.title}' -> ${target.completed ? 'Completed' : 'Pending'}`;
}

button.on_click:
try {
    const toolName = $data.simulated_tool_selected;
    const rawPayload = $data.simulated_tool_payload;
    const parsedArgs = rawPayload && rawPayload.trim() ? JSON.parse(rawPayload) : {};

    $data.simulation_log = `AI Agent executing '${toolName}'...`;

    if ($engine.webmcp) {
        const nativeCtx = $engine.webmcp.getNativeContext() || window._mockWebMCP;
        if (nativeCtx && typeof nativeCtx.executeTool === 'function') {
            nativeCtx.executeTool(toolName, parsedArgs)
                .then(res => {
                    $engine.setState('simulation_log', `✓ Success: ${JSON.stringify(res)}`);
                })
                .catch(err => {
                    $engine.setState('simulation_log', `⚠ Error: ${err.message}`);
                });
        } else {
            // Direct execution via Action Composer fallback
            if (toolName === 'create_ticket') {
                $engine.executeAction('ticket.create', parsedArgs);
            } else if (toolName === 'toggle_ticket') {
                $engine.executeAction('ticket.toggle', parsedArgs);
            } else if (toolName === 'list_tickets') {
                $engine.executeAction('ticket.list', parsedArgs);
            } else if (toolName === 'search_tickets') {
                $engine.executeAction('ticket.query', parsedArgs);
            }
            $data.simulation_log = `✓ Invoked '${toolName}' with payload: ${JSON.stringify(parsedArgs)}`;
        }
    }
} catch (e) {
    $data.simulation_log = `Error parsing JSON args: ${e.message}`;
}
